        .into_iter()
        .map(|(logical, destination)| {
            let key = |raw: String| {
                callisto_model::validated_registry_key(raw).map_err(|error| ConfigError::InvalidProductRelease {
                    detail: format!("release profile `{name}` has an invalid registry route: {error}"),
                })
